options.helpers:
const selSev = context.grafana.replaceVariables('${severity}');

context.handlebars.registerHelper('severityMatch', function(badge, options) {
  const cur = context.grafana.replaceVariables('${severity}');
  if (!cur || cur === 'All' || cur === '.*' || cur === '' || cur === badge) {
    return options.fn(this);
  }
  return options.inverse(this);
});

context.handlebars.registerHelper('hasVisibleIssues', function(data, options) {
  if (!data || !Array.isArray(data)) return options.inverse(this);
  const cur = context.grafana.replaceVariables('${severity}');
  const visible = data.filter(function(r) {
    if (!r || !r.Headline) return false;
    return !cur || cur === 'All' || cur === '.*' || cur === '' || cur === r.SeverityBadge;
  });
  if (visible.length > 0) {
    return options.fn(this);
  }
  return options.inverse(this);
});

context.handlebars.registerHelper('currentSeverity', function() {
  const cur = context.grafana.replaceVariables('${severity}');
  return (!cur || cur === '.*') ? 'All' : cur;
});

context.handlebars.registerHelper('urlTimeRange', function() {
  return context.grafana.replaceVariables('${__url_time_range}') || 'from=now-5m&to=now';
});

options.afterRender:
const selSev = context.grafana.replaceVariables('${severity}');
const el = context.element;
if (el) {
  const rows = el.querySelectorAll('tbody tr.tn-row');
  let visibleCount = 0;
  rows.forEach(function(r) {
    const badge = r.getAttribute('data-severity');
    if (!selSev || selSev === 'All' || selSev === '.*' || selSev === '' || selSev === badge) {
      r.style.setProperty('display', '', 'important');
      visibleCount++;
    } else {
      r.style.setProperty('display', 'none', 'important');
    }
  });
}

options.styles:
.tn-table-wrapper {
  width: 100%;
  overflow-x: auto;
  padding: 0;
  margin: 0;
}

.tn-issues-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  font-family: Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #e2e8f0;
}

.tn-issues-table thead th {
  text-align: left;
  padding: 10px 14px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #94a3b8;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(15, 23, 42, 0.6);
  white-space: nowrap;
}

.tn-row {
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  transition: background 0.15s ease;
}

.tn-row:hover {
  background: rgba(255, 255, 255, 0.04);
}

.tn-row td {
  padding: 10px 14px;
  vertical-align: middle;
}

.tn-sev-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.tn-cell-issue {
  font-weight: 600;
  color: #f1f5f9;
}

.tn-cell-scope {
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 12px;
  color: #cbd5e1;
}

.tn-cell-value {
  font-size: 13.5px;
  white-space: nowrap;
}

.tn-cell-muted {
  color: #94a3b8;
  font-size: 12.5px;
  white-space: nowrap;
}

.tn-investigate-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 12px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  color: #38bdf8;
  text-decoration: none;
  background: rgba(56, 189, 248, 0.08);
  border: 1px solid rgba(56, 189, 248, 0.25);
  transition: all 0.2s ease;
  white-space: nowrap;
}

.tn-investigate-link:hover {
