}

.tn-healthy-icon {
  font-size: 32px;
}

.tn-healthy-title {
  font-size: 16px;
  font-weight: 700;
  color: #10b981;
  margin-bottom: 2px;
}

.tn-healthy-sub {
  font-size: 13px;
  color: #94a3b8;
}
